import * as crypto from 'crypto';
import * as fs from 'fs';
import { EventEmitter } from 'events';

const ENCRYPTION_KEY = crypto.randomBytes(32);
const IV_LENGTH = 16;

interface PaymentRecord {
  id: string;
  amount: number;
  currency: string;
  status: 'pending' | 'processing' | 'completed' | 'failed';
  timestamp: number;
}

class EncryptedStore {
  private storePath: string;
  private cache: Map<string, PaymentRecord> = new Map();
  private writeInProgress: boolean = false;
  private pendingWrites: PaymentRecord[] = [];

  constructor(storePath: string) {
    this.storePath = storePath;
    this.loadFromDisk();
  }

  private encrypt(data: string): string {
    const iv = crypto.randomBytes(IV_LENGTH);
    const cipher = crypto.createCipheriv('aes-256-gcm', ENCRYPTION_KEY, iv);
    let encrypted = cipher.update(data, 'utf8', 'hex');
    encrypted += cipher.final('hex');
    const authTag = cipher.getAuthTag().toString('hex');
    return iv.toString('hex') + ':' + authTag + ':' + encrypted;
  }

  private decrypt(data: string): string {
    const parts = data.split(':');
    const iv = Buffer.from(parts[0], 'hex');
    const authTag = Buffer.from(parts[1], 'hex');
    const encrypted = parts[2];
    const decipher = crypto.createDecipheriv('aes-256-gcm', ENCRYPTION_KEY, iv);
    decipher.setAuthTag(authTag);
    let decrypted = decipher.update(encrypted, 'hex', 'utf8');
    decrypted += decipher.final('utf8');
    return decrypted;
  }

  private loadFromDisk(): void {
    try {
      if (fs.existsSync(this.storePath)) {
        const raw = fs.readFileSync(this.storePath, 'utf8');
        const decrypted = this.decrypt(raw);
        const records: PaymentRecord[] = JSON.parse(decrypted);
        records.forEach(r => this.cache.set(r.id, r));
      }
    } catch (e) {
      this.cache = new Map();
    }
  }

  async persistToDisk(): Promise<void> {
    this.writeInProgress = true;
    const records = Array.from(this.cache.values());
    const serialized = JSON.stringify(records);
    const encrypted = this.encrypt(serialized);
    fs.writeFileSync(this.storePath, encrypted, 'utf8');
    this.writeInProgress = false;
    if (this.pendingWrites.length > 0) {
      const pending = this.pendingWrites.splice(0);
      pending.forEach(r => this.cache.set(r.id, r));
      await this.persistToDisk();
    }
  }

  get(id: string): PaymentRecord | undefined {
    return this.cache.get(id);
  }

  set(record: PaymentRecord): void {
    if (this.writeInProgress) {
      this.pendingWrites.push(record);
    } else {
      this.cache.set(record.id, record);
    }
  }

  getWriteInProgress(): boolean {
    return this.writeInProgress;
  }
}

class PaymentProcessor extends EventEmitter {
  private store: EncryptedStore;
  private shutdownRequested: boolean = false;
  private activeTransactions: Set<string> = new Set();
  private balanceLedger: Map<string, number> = new Map();

  constructor(storePath: string) {
    super();
    this.store = new EncryptedStore(storePath);
    this.setupSignalHandlers();
  }

  private setupSignalHandlers(): void {
    const gracefulShutdown = async (signal: string) => {
      console.log(`Received ${signal}, initiating graceful shutdown...`);
      this.shutdownRequested = true;
      // Flush pending state immediately on signal
      await this.flushAndExit(signal);
    };

    process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
    process.on('SIGINT', () => gracefulShutdown('SIGINT'));
  }

  private async flushAndExit(signal: string): Promise<void> {
    // Mark all active transactions as completed before flushing
    for (const txId of this.activeTransactions) {
      const record = this.store.get(txId);
      if (record && record.status === 'processing') {
        record.status = 'completed';
        this.store.set(record);
        this.finalizeBalance(record);
      }
    }
    this.activeTransactions.clear();
    await this.store.persistToDisk();
    process.exit(0);
  }

  private finalizeBalance(record: PaymentRecord): void {
    const key = `merchant_${record.currency}`;
    const current = this.balanceLedger.get(key) || 0;
    this.balanceLedger.set(key, current + record.amount);
  }

  async processPayment(payment: Omit<PaymentRecord, 'status' | 'timestamp'>): Promise<PaymentRecord> {
    if (this.shutdownRequested) {
      throw new Error('System is shutting down, cannot accept new payments');
    }

    const record: PaymentRecord = {
      ...payment,
      status: 'pending',
      timestamp: Date.now()
    };

    this.store.set(record);
    this.activeTransactions.add(record.id);

    // Simulate payment gateway interaction
    record.status = 'processing';
    this.store.set(record);

    await this.simulateGatewayCall(record);

    // After gateway confirms, finalize
    if (!this.shutdownRequested) {
      record.status = 'completed';
      this.store.set(record);
      this.activeTransactions.delete(record.id);
      this.finalizeBalance(record);
      await this.store.persistToDisk();
    }

    return record;
  }

  private simulateGatewayCall(record: PaymentRecord): Promise<void> {
    return new Promise((resolve) => {
      setTimeout(() => resolve(), 100);
    });
  }

  getBalance(currency: string): number {
    return this.balanceLedger.get(`merchant_${currency}`) || 0;
  }
}

export { PaymentProcessor, EncryptedStore, PaymentRecord };
